const zone = 'America/Toronto';
const now = DateTime.now().setZone(zone);
const clean = (v) => (v === undefined || v === null ? '' : String(v).trim());
const memory = $('Read Memory Tab').all().map(i => i.json).filter(r => r && clean(r.id) && clean(r.note));
const actions = $('Read Actions Tab').all().map(i => i.json).filter(r => r && clean(r.id));
const parse = (v) => { let d = DateTime.fromFormat(clean(v), 'yyyy-MM-dd HH:mm', { zone }); if (!d.isValid) d = DateTime.fromISO(clean(v), { zone }); return d.isValid ? d : null; };
const doneLog = memory.filter(r => clean(r.type).toLowerCase() === 'done');
const active = memory
  .filter(r => clean(r.type).toLowerCase() !== 'done')
  .filter(r => !['done', 'archived'].includes(clean(r.status).toLowerCase()))
  .filter(r => { const d = parse(r.captured_at); return !d || d >= now.minus({ days: 30 }); });
const activeText = active.map(r => {
  const id = clean(r.id);
  const doneFor = doneLog.filter(d => clean(d.note).toUpperCase().includes(`[${id.toUpperCase()}]`)).map(d => `    already done: ${clean(d.note)}`);
  return [`- ${id} (row ${clean(r.row_number)}, captured ${clean(r.captured_at)}): ${clean(r.note)}`, ...doneFor].join('\n');
}).join('\n');
const openActions = actions.filter(a => clean(a.approval_status).toLowerCase() !== 'rejected');
const actionsText = openActions.map(a => `- ${clean(a.id)} [${clean(a.approval_status) || 'pending'}${clean(a.outcome).startsWith('http') ? ', draft already created' : ''}]: ${clean(a.proposed_action)}`).join('\n');
return [{ json: {
  message: clean($('Normalize Note').first().json.note),
  active_text: activeText || '(none)',
  actions_text: actionsText || '(none)',
  active_ids: active.map(r => clean(r.id).toUpperCase()),
  open_action_ids: openActions.map(a => clean(a.id).toUpperCase())
} }];

const ctx = $('Build Context').first().json;
const o = ($input.first().json && $input.first().json.output) || {};
const clean = (v) => (v === undefined || v === null ? '' : String(v).trim());
const up = (v) => clean(v).toUpperCase();
const stamp = DateTime.now().setZone('America/Toronto').toFormat('yyyy-MM-dd HH:mm');
const exec = $execution.id;
const msg = ctx.message;
const activeIds = new Set(ctx.active_ids || []);
const openActions = new Set(ctx.open_action_ids || []);

// Done items: only rows that really exist and are active
const seen = new Set();
const done = (o.done_items || [])
  .filter(d => activeIds.has(up(d.ref_id)) && clean(d.item))
  .filter(d => { const k = up(d.ref_id) + '|' + clean(d.item).toLowerCase(); if (seen.has(k)) return false; seen.add(k); return true; })
  .slice(0, 5);
const doneRows = done.map((d, i) => ({
  id: `D-${exec}-${i + 1}`, captured_at: stamp, type: 'done',
  title: `Done: ${clean(d.item)}`.slice(0, 60), note: `Done: ${clean(d.item)} [${up(d.ref_id)}]`,
  status: 'done', source: 'chat'
}));
const closeRows = [...new Set(done.filter(d => d.closes_whole_row === true).map(d => up(d.ref_id)))]
  .map(id => ({ id, status: 'done', last_updated: stamp }));

// Approvals: deterministic match on the message text, plus the model's reading, limited to real open actions
const requested = new Set((o.approve_action_ids || []).map(up));
if (/approv|go ahead|green ?light|yes,? (do|draft)/i.test(msg)) for (const m of (msg.match(/\bA-\d+\b/gi) || [])) requested.add(up(m));
const approvals = [...requested].filter(id => openActions.has(id));
const unknownApprovals = [...requested].filter(id => !openActions.has(id));

// New note
let saveNote = o.save_note === true && clean(o.note_text) !== '';
const fileCount = $('Normalize Note').first().json.file_count || 0;
if (fileCount > 0) saveNote = false; // the message is the caption for the uploaded files
if (!saveNote && !done.length && !requested.size && !fileCount && msg) saveNote = true; // never lose input
const noteText = clean(o.note_text) || msg;
const lowerMsg = msg.toLowerCase();
const person = clean(o.person_or_project);
const personOk = person && person.split(/\s+/).every(w => lowerMsg.includes(w.toLowerCase().replace(/[^a-z0-9]/g, '')));
let due = clean(o.due_date);
if (!/^\d{4}-\d{2}-\d{2}$/.test(due) || !msg.includes(String(parseInt(due.slice(8, 10), 10)))) due = '';
const title = (clean(o.note_title) || noteText).replace(/\s+/g, ' ');
const noteRow = {
  id: `M-${exec}`, captured_at: stamp, type: 'note',
  title: title.length > 60 ? title.slice(0, 57).trimEnd() + '...' : title,
  note: noteText, person_or_project: personOk ? person : '', due_date: due, status: 'new', source: 'chat'
};

return [{ json: {
  save_note: saveNote, note_row: noteRow,
  done_rows: doneRows, close_rows: closeRows, approvals, unknown_approvals: unknownApprovals,
  done_summary: done.map(d => ({ item: clean(d.item), ref: up(d.ref_id), closes: d.closes_whole_row === true })),
  has_done: doneRows.length > 0, has_close: closeRows.length > 0, has_approvals: approvals.length > 0
} }];

const p = $('Plan Changes').first().json;
let files = [];
try { files = $('Run File Intake').all().map(i => i.json); } catch (e) { files = []; }
let drafts = [];
try { drafts = $('Run Draft Builder').all().map(i => i.json); } catch (e) { drafts = []; }
const lines = [];
if (p.save_note) lines.push(`✅ **Saved ${p.note_row.id}:** ${p.note_row.title}`);
for (const d of p.done_summary) lines.push(`☑️ **Marked done:** ${d.item} [${d.ref}]${d.closes ? ` (all of ${d.ref} is now done)` : ''}`);
for (const r of drafts) {
  if (r.ok && r.url) lines.push(`📄 **${r.action_id} draft ready:** [${r.title || 'Open draft'}](${r.url})`);
  else if (r.url) lines.push(`📄 ${r.action_id} already has a draft: [open it](${r.url})`);
  else lines.push(`⚠️ ${r.action_id}: ${r.message || 'could not create the draft'}`);
}
for (const f of files) {
  const icon = f.extraction_status === 'extracted' ? '📎' : '⚠️';
  lines.push(`${icon} **Saved ${f.id}:** [${f.file_name}](${f.file_url}) (${f.file_type}) — ${f.short_summary}`);
}
const expected = $('Normalize Note').first().json.file_count || 0;
if (expected && files.length < expected) lines.push(`⚠️ ${expected - files.length} file(s) did not finish uploading.`);
if (p.has_approvals && !drafts.length) lines.push('⚠️ The draft step did not return a result. Check the Draft Builder workflow.');
for (const id of p.unknown_approvals) lines.push(`⚠️ ${id} is not an open action, so nothing was created.`);
if (!lines.length) lines.push('Nothing to save in that message.');
lines.push('', '_Drafts only. Nothing was sent._');
return [{ json: { output: lines.join('\n') } }];

const bin = $('Chat Input').first().binary || {};
const exec = $execution.id;
const caption = $('Normalize Note').first().json.note || '';
return Object.keys(bin).map((k, i) => {
  const b = bin[k];
  const mime = b.mimeType || '';
  const kind = mime === 'application/pdf' ? 'pdf' : (mime.startsWith('image/') ? 'image' : 'other');
  return { json: { file_id: `F-${exec}-${i + 1}`, file_name: b.fileName || `upload-${i + 1}`, mime_type: mime, kind, caption }, binary: { data: b } };
});
